def minMergeCost(nums):
    stack = [10 ** 9]  # sentinel, larger than any value
    cost = 0
    for x in nums:
        while stack[-1] <= x:
            mid = stack.pop()
            cost += mid * min(stack[-1], x)
        stack.append(x)
    while len(stack) > 2:
        cost += stack.pop() * stack[-1]
    return cost
